for base in ['app/admin','app/publisher','components/admin','components/publisher','components/dashboard','lib/settings','app/api/admin','app/api/publisher']:
    d = root / base
    if not d.exists():
        continue
    for p in d.rglob('*'):
        if p.suffix in {'.ts', '.tsx', '.js', '.jsx'}:
            text = p.read_text(encoding='utf-8')
            new_text = text
            for old, new in repl.items():
                new_text = new_text.replace(old, new)
            if new_text != text:
                p.write_text(new_text, encoding='utf-8')
                print(p.relative_to(root))
